cd /home/user/rork-app

# Compute md5 + verify APK integrity
APK=expo/android/app/build/outputs/apk/release/app-release.apk
MD5=$(md5sum "$APK" | awk '{print $1}')
SHA=$(sha256sum "$APK" | awk '{print $1}')
SIZE=$(stat -c%s "$APK")
echo "APK: $SIZE bytes"
echo "md5: $MD5"
echo "sha256: $SHA"

# Verify versionCode inside the APK
echo ""
echo "=== APK version verification ==="
unzip -p "$APK" assets/app.config 2>/dev/null | head -c 500 || echo "(no app.config asset — checking AndroidManifest)"
node -e "
const { execSync } = require('child_process');
try {
  const out = execSync('aapt dump badging \"' + '$APK' + '\" 2>/dev/null || true').toString();
  const vc = out.match(/versionCode='(\\d+)'/);
  const vn = out.match(/versionName='([^']+)'/);
  console.log('versionCode:', vc ? vc[1] : 'NOT FOUND');
  console.log('versionName:', vn ? vn[1] : 'NOT FOUND');
} catch(e) { console.log('aapt not available'); }
"

echo ""
echo "MD5_SAVE=$MD5" > /tmp/apk-meta.env
echo "SIZE_SAVE=$SIZE" >> /tmp/apk-meta.env
echo "SHA_SAVE=$SHA" >> /tmp/apk-meta.env

